def minRemovals(grid):
    rows, cols = len(grid), len(grid[0])
    cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]
    if not cells:
        return 0
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    # connectivity from the first cell
    start = cells[0]
    seen = {start}
    stack = [start]
    while stack:
        y, x = stack.pop()
        for dy, dx in dirs:
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1 and (ny, nx) not in seen:
                seen.add((ny, nx))
                stack.append((ny, nx))
    if len(seen) != len(cells):
        return 0
    if len(cells) == 1:
        return 1
    # articulation points with an iterative DFS
    disc = {}
    low = {}
    timer = 0
    disc[start] = low[start] = timer
    timer += 1
    root_children = 0
    work = [(start, None, iter(dirs))]
    while work:
        v, parent, it = work[-1]
        advanced = False
        for dy, dx in it:
            u = (v[0] + dy, v[1] + dx)
            if not (0 <= u[0] < rows and 0 <= u[1] < cols) or grid[u[0]][u[1]] != 1:
                continue
            if u not in disc:
                disc[u] = low[u] = timer
                timer += 1
                if v == start:
                    root_children += 1
                work.append((u, v, iter(dirs)))
                advanced = True
                break
            elif u != parent:
                low[v] = min(low[v], disc[u])
        if advanced:
            continue
        work.pop()
        if parent is not None:
            low[parent] = min(low[parent], low[v])
            if parent != start and low[v] >= disc[parent]:
                return 1
    if root_children >= 2:
        return 1
    return 2
